 {tab==='recorridos'&&<RoutesPanel period={p} employees={periodEmployees} readOnly={readOnly} busy={busy||dirty} onEdit={show=>setModal({kind:'route',value:show})} onLegacy={route=>setModal({kind:'legacyRoute',value:route})} onExtra={route=>setModal({kind:'extraRoute',value:route})} onRemove={id=>remove('routes',id)}/>}
 {tab==='horas'&&<section className="panel"><div className="panel-title"><h2>Horas y salarios</h2><span className="muted">Base mensual ÷ {totals.settings.hourDivisor}</span></div><p className="panel-note">Registra las horas por tipo. Las horas ordinarias están incluidas en el salario. {p.ownerOnly&&!locked?'Para ajustar bases y descuentos de este corte, abre el detalle de la persona en Liquidación.':'La base y los descuentos se editan en Personal.'}</p><Table><TableHeader><TableRow><TableHead>Persona</TableHead><TableHead>Días</TableHead><TableHead>Horas adicionales</TableHead><TableHead className="numeric">Pago neto</TableHead><TableHead/></TableRow></TableHeader><TableBody>{(locked?periodEmployees.filter(e=>e.active&&!e.deleted):active).filter(e=>e.salary>0).map(e=>{const h=p.hours.find(h=>h.employeeId===e.id);const row=totals.rows.find(r=>r.employeeId===e.id&&r.category==='administracion');return <TableRow key={e.id}><TableCell><strong>{e.name}</strong><small>{e.cycle==='mensual'?'Pago mensual · '+(e.monthlyHalf===1?'Primera':'Segunda')+' quincena':'Pago quincenal'}{!e.pension?' · Sin AFP':''}</small></TableCell><TableCell>{row?(h?.days??(e.cycle==='mensual'?30:15)):'—'}</TableCell><TableCell>{h?.counts.reduce((a,b)=>a+b,0)||0}</TableCell><TableCell className="numeric">{row?money(row.net):'Fuera de este corte'}</TableCell><TableCell>{!readOnly&&<Button variant="outline" disabled={busy||dirty} onClick={()=>setModal({kind:'hours',value:e})}><Pencil/>Novedades</Button>}</TableCell></TableRow>;})}</TableBody></Table></section>}
 {tab==='pagos'&&<section className="panel"><div className="panel-title"><h2>Liquidación por persona</h2><Input aria-label="Buscar en la liquidación" placeholder="Buscar persona…" value={search} onChange={e=>setSearch(e.target.value)} className="search"/></div><div className="filters"><button className={filter==='todos'?'selected':''} onClick={()=>setFilter('todos')}>Todos</button>{categories.map(c=><button key={c} className={filter===c?'selected':''} onClick={()=>setFilter(c)}>{categoryNames[c]}</button>)}</div><Table><TableHeader><TableRow><TableHead>Persona</TableHead><TableHead className="numeric">Devengado</TableHead><TableHead className="numeric">Adiciones</TableHead><TableHead className="numeric">Descuentos</TableHead><TableHead className="numeric">Neto</TableHead></TableRow></TableHeader><TableBody>{rows.map(r=><TableRow key={r.employeeId+r.category}><TableCell><button className="person-link" onClick={()=>setModal({kind:'detail',value:r.employeeId})}>{r.name}</button><small>{categoryNames[r.category]}</small></TableCell><TableCell className="numeric">{money(r.gross)}</TableCell><TableCell className="numeric">{money(r.reimbursements)}</TableCell><TableCell className="numeric deduction">{money(r.deductions)}</TableCell><TableCell className="numeric net">{money(r.net)}</TableCell></TableRow>)}</TableBody></Table>{!rows.length&&<p className="panel-note">No hay pagos que coincidan con esta selección.</p>}</section>}
